"""Intent tests for risk.summary_stats (M1-T19, RISK-04, TC-07)."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


@pytest.mark.intent
def test_tc07_whole_period_summary_matches_golden(golden):
    inp, expected = golden("risk", "TC-07")
    tol = expected["tol"]

    result = summary_stats(_vol(inp["vol"]))

    assert isinstance(result, tuple)
    assert [s.ticker for s in result] == [row["ticker"] for row in expected["summary"]]
    for got, want in zip(result, expected["summary"], strict=True):
        assert isinstance(got, TickerSummary)
        assert got.ann_return == pytest.approx(want["ann_return"], abs=tol)
        assert got.ann_vol == pytest.approx(want["ann_vol"], abs=tol)
        assert got.sharpe == pytest.approx(want["sharpe"], abs=tol)
        if want["last_vol"] is None:
            assert got.last_vol is None
        else:
            assert got.last_vol == pytest.approx(want["last_vol"], abs=tol)


@pytest.mark.intent
def test_tc07_zero_volatility_ticker_has_zero_sharpe(golden):
    inp, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    want = next(row for row in expected["summary"] if row["ticker"] == "Y")

    result = {s.ticker: s for s in summary_stats(_vol(inp["vol"]))}

    assert result["Y"].ann_vol == pytest.approx(want["ann_vol"], abs=tol)
    assert result["Y"].sharpe == pytest.approx(want["sharpe"], abs=tol)


@pytest.mark.intent
def test_tc07_explicit_252_periods_matches_default(golden):
    inp, expected = golden("risk", "TC-07")
    tol = expected["tol"]

    result = summary_stats(_vol(inp["vol"]), periods_per_year=252)

    for got, want in zip(result, expected["summary"], strict=True):
        assert got.ticker == want["ticker"]
        assert got.ann_return == pytest.approx(want["ann_return"], abs=tol)
        assert got.ann_vol == pytest.approx(want["ann_vol"], abs=tol)


@pytest.mark.intent
def test_summary_one_row_per_ticker_in_returns_order(contract_sample):
    vol = _vol(contract_sample("risk.VolSeries"))

    result = summary_stats(vol)

    assert tuple(s.ticker for s in result) == vol.returns.tickers


@pytest.mark.intent
def test_fewer_than_two_returns_raises_value_error(contract_sample):
    payload = contract_sample("risk.VolSeries")
    rets = payload["returns"]
    one = {
        "returns": {
            "base_date": rets["base_date"],
            "dates": rets["dates"][:1],
            "tickers": rets["tickers"],
            "values": {t: v[:1] for t, v in rets["values"].items()},
        },
        "window": payload["window"],
        "annualized": payload["annualized"],
        "values": {t: v[:1] for t, v in payload["values"].items()},
    }

    with pytest.raises(ValueError, match=r"(?i)two|2|returns"):
        summary_stats(_vol(one))

